fn sum(nums: &[i32]) -> i32 {
    let mut total = 0;
    for n in nums {
        total += n;
    }
    total
}

fn main() {
    let a = [1, 2, 3, 4];
    println!("{}", sum(&a[2..]));
}

fn first_word(s: &str) -> &str {
    for (i, ch) in s.char_indices() {
        if ch == ' ' {
            return &s[..i];
        }
    }
    s
}

fn main() {
    let t = String::from("  hi there");
    println!("[{}]", first_word(&t));
}
